from pathlib import Path
import sys
w=Path(sys.argv[1]);p=w/'apps/api/tests/studio/integration.test.ts';s=p.read_text();s="import { AsyncLocalStorage } from 'node:async_hooks';\n"+s
marker="it('R4 real COMMIT first/update/history snapshots keep production and dev browser current, preview, ZIP and retirement coherent', async () => {"
insert='''
  const spans: unknown[] = [], restorations: (()=>void)[] = [], clock = performance.now();
  const trace = new AsyncLocalStorage<number>(); let seq = 0;
  function wrap(prototype: any, name: string, group: string) {
    const original = prototype[name]; if (typeof original !== 'function') return;
    prototype[name] = async function(...args: any[]) {
      const id=++seq, parent=trace.getStore(), start=performance.now(), cpu=process.cpuUsage();
      let gateStart: number|undefined;
      if(group==='gate' && name==='run') { const operation=args[1];args[1]=async(...a:any[])=>{gateStart=performance.now();return operation(...a);}; }
      return trace.run(id,async()=>{try {return await original.apply(this,args);} finally {
        const used=process.cpuUsage(cpu);spans.push({id,parent,group,name,startMs:Math.round(start-clock),ms:Math.round(performance.now()-start),setupWaitMs:gateStart===undefined?undefined:Math.round(gateStart-start),nodeCpuUserUs:used.user,nodeCpuSystemUs:used.system});
      }});
    };
    restorations.push(()=>prototype[name]=original);
  }
  for(const name of ['readSource','readDomainRecipe','loadArchives','readBuild','readExport','prepareBuild','publish','publishVerified','transaction','adopt','projectSnapshot']) wrap(Persistence.prototype,name,'store');
  for(const name of ['state','recipe','enqueue','execute','processed','export','detail','write']) wrap(StudioService.prototype,name,'service');
  for(const name of ['read','put','buildFiles','publish']) wrap(Object.getPrototypeOf(service.store.storage),name,'storage');
  wrap(Object.getPrototypeOf(service.store.gate),'run','gate');
'''
assert s.count(marker)==1;s=s.replace(marker,marker+insert)
end="    await writeFile(resolve(root, 'r4-vite.log'), viteLog.join(''));\n  }\n});";assert s.count(end)==1;s=s.replace(end,"    await writeFile(resolve(root, 'r4-vite.log'), viteLog.join(''));\n    for(const restore of restorations.reverse())restore();\n    await record('r4-detailed-spans',{sourceContext:resources.context,spans});\n  }\n});")
p.write_text(s)
